<?php
/**
 * BdThemes deals biggopti, shared by every BdThemes free plugin.
 *
 * Each plugin ships an identical copy of this file (only the text domain
 * differs). The class_exists() guard lets the first copy that loads register
 * the biggopti, so the biggopti shows once no matter how many BdThemes plugins are
 * active. The biggopti id and the option key are the same in every copy, so
 * dismissing it from any plugin hides it everywhere, for good.
 *
 * @package BdThemes
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( ! class_exists( 'BdThemes_Deals_Biggopti' ) ) {

	final class BdThemes_Deals_Biggopti {

		/**
		 * Shared across every BdThemes plugin. Change it to show a new campaign.
		 */
		const BIGGOPTI_ID = 'bdthemes_deals_2026';

		/**
		 * Option (wp_options) holding the ids of the dismissed BdThemes biggopties.
		 * Site-wide: once any administrator dismisses a biggopti it stays hidden.
		 */
		const OPTION_KEY = 'bdthemes_dismissed_biggopties';

		const ACTION = 'bdthemes_dismiss_biggopti';

		/**
		 * Screens the biggopti shows on: the WordPress Dashboard, the Plugins screen and
		 * each BdThemes free plugin's own dashboard. Only the first copy to load
		 * registers the biggopti, so this list covers every plugin.
		 */
		const SCREENS = [
			'dashboard',
			'plugins',
			'toplevel_page_element_pack_options',        // Element Pack Lite.
			'toplevel_page_prime_slider_options',        // Prime Slider.
			'toplevel_page_ultimate_post_kit_options',   // Ultimate Post Kit.
			'toplevel_page_ultimate-store-kit',          // Ultimate Store Kit.
			'toplevel_page_pixel_gallery_options',       // Pixel Gallery.
			'toplevel_page_zoloblocks',                  // ZoloBlocks.
			'toplevel_page_smart-admin-assistant',       // Smart Admin Assistant.
			'toplevel_page_website-accessibility',       // One Accessibility.
			'toplevel_page_dark-reader-settings',        // Dark Reader.
			'settings_page_ai-image-settings',           // AI Image.
			'edit-swp_wheel',                            // Spin Wheel.
		];

		const DEALS_URL = 'https://bdthemes.com/deals/?utm_source=wp_admin&utm_medium=admin_biggopti&utm_campaign=deals';

		public static function init() {
			add_action( 'admin_notices', [ __CLASS__, 'render' ] );
			add_action( 'wp_ajax_' . self::ACTION, [ __CLASS__, 'ajax_dismiss' ] );
			add_action( 'admin_init', [ __CLASS__, 'link_dismiss' ] );
		}

		/**
		 * Shown to administrators on the screens listed in SCREENS.
		 */
		private static function should_show() {
			if ( ! current_user_can( 'manage_options' ) ) {
				return false;
			}

			$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;

			return $screen && in_array( $screen->id, self::SCREENS, true ) && ! self::is_dismissed();
		}

		public static function is_dismissed() {
			$dismissed = get_option( self::OPTION_KEY, [] );

			return is_array( $dismissed ) && in_array( self::BIGGOPTI_ID, $dismissed, true );
		}

		private static function dismiss() {
			$dismissed = get_option( self::OPTION_KEY, [] );
			$dismissed = is_array( $dismissed ) ? $dismissed : [];

			if ( ! in_array( self::BIGGOPTI_ID, $dismissed, true ) ) {
				$dismissed[] = self::BIGGOPTI_ID;
				update_option( self::OPTION_KEY, $dismissed );
			}
		}

		public static function render() {
			if ( ! self::should_show() ) {
				return;
			}

			$nonce   = wp_create_nonce( self::ACTION );
			$screen  = get_current_screen();
			$classes = 'notice notice-info bdthemes-deals-biggopti';

			// WordPress moves notices below the first heading in .wrap. On the plugin
			// dashboards that heading belongs to the plugin's own (often React) UI, so
			// keep the biggopti where it is printed, above that UI.
			if ( ! in_array( $screen->id, [ 'dashboard', 'plugins' ], true ) ) {
				$classes .= ' inline';
			}

			$skip_url = add_query_arg(
				[
					self::ACTION => self::BIGGOPTI_ID,
					'_wpnonce'   => $nonce,
				]
			);
			?>
			<div class="<?php echo esc_attr( $classes ); ?>" data-biggopti="<?php echo esc_attr( self::BIGGOPTI_ID ); ?>" data-nonce="<?php echo esc_attr( $nonce ); ?>">
				<div class="bdthemes-deals-biggopti__content">
					<p class="bdthemes-deals-biggopti__title">
						<?php esc_html_e( 'Build More. Spend Less.', 'bdthemes-prime-slider-lite' ); ?>
						<span class="bdthemes-deals-biggopti__highlight"><?php esc_html_e( 'Save Up to $4,899', 'bdthemes-prime-slider-lite' ); ?></span>
					</p>
					<p class="bdthemes-deals-biggopti__text"><?php esc_html_e( 'Customize your agency bundle with 14 plugins to choose from Element Pack, Post Kit, Store Kit, Prime Slider, Pixel Gallery, One Accessibility, Spin Wheel & more.', 'bdthemes-prime-slider-lite' ); ?></p>
					<p class="bdthemes-deals-biggopti__actions">
						<a href="<?php echo esc_url( self::DEALS_URL ); ?>" class="button button-primary bdthemes-deals-biggopti__cta" target="_blank" rel="noopener noreferrer"><?php esc_html_e( 'Grab the Deal', 'bdthemes-prime-slider-lite' ); ?></a>
						<a href="<?php echo esc_url( $skip_url ); ?>" class="bdthemes-deals-biggopti__skip"><?php esc_html_e( 'Don’t Show Again', 'bdthemes-prime-slider-lite' ); ?></a>
					</p>
				</div>
