			<style>
				.bdthemes-deals-biggopti.notice { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 8.3px 20.7px 8.3px 29px; border: 0; background: #fff; box-shadow: none; }
				.bdthemes-deals-biggopti__content { flex: 1 1 auto; min-width: 0; padding-top: 1.05px; }
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__title,
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__text,
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__actions { margin: 0; padding: 0; font-size: 13px; line-height: 19.5px; color: #000; }
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__title { font-weight: 500; }
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__text { max-width: 680px; margin-top: 10px; }
				.bdthemes-deals-biggopti__highlight { padding: 3px 5px 2.65px; border-radius: 3px; background: #e5ebf8; font-weight: 700; }
				.bdthemes-deals-biggopti .bdthemes-deals-biggopti__actions { display: flex; align-items: center; gap: 15px; margin-top: 13.15px; }
				.wp-core-ui .bdthemes-deals-biggopti .bdthemes-deals-biggopti__cta { min-width: 127px; min-height: 34px; padding: 0 19px; border-radius: 2px; font-size: 13px; font-weight: 400; line-height: 32px; text-align: center; }
				.bdthemes-deals-biggopti a.bdthemes-deals-biggopti__skip { color: #3858e9; font-size: 13px; line-height: 19.5px; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4.75px; }
				.bdthemes-deals-biggopti a.bdthemes-deals-biggopti__skip:hover { color: #2145e6; }
				.bdthemes-deals-biggopti__badge { flex: 0 0 auto; width: 135.5px; height: 135.5px; }
				@media screen and (max-width: 782px) { .bdthemes-deals-biggopti__badge { display: none; } }
			</style>
			<script>
				( function () {
					var biggopti = document.querySelector( '.bdthemes-deals-biggopti' );

					if ( ! biggopti ) {
						return;
					}

					biggopti.addEventListener( 'click', function ( event ) {
						if ( ! event.target.closest( '.bdthemes-deals-biggopti__skip' ) ) {
							return;
						}

						var body = new FormData();

						event.preventDefault();
						biggopti.style.display = 'none';

						body.append( 'action', '<?php echo esc_js( self::ACTION ); ?>' );
						body.append( 'biggopti', biggopti.getAttribute( 'data-biggopti' ) );
						body.append( '_wpnonce', biggopti.getAttribute( 'data-nonce' ) );

						fetch( <?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>, { method: 'POST', credentials: 'same-origin', body: body } );
					} );
				} )();
			</script>
			<?php
		}

		public static function ajax_dismiss() {
			check_ajax_referer( self::ACTION );

			if ( ! current_user_can( 'manage_options' ) ) {
				wp_send_json_error( null, 403 );
			}

			$biggopti = isset( $_POST['biggopti'] ) ? sanitize_key( wp_unslash( $_POST['biggopti'] ) ) : '';

			if ( self::BIGGOPTI_ID !== $biggopti ) {
				wp_send_json_error( null, 400 );
			}

			self::dismiss();
			wp_send_json_success();
		}

		/**
		 * "Don’t Show Again" without JavaScript: dismiss, then drop the query args.
		 */
		public static function link_dismiss() {
			if ( ! isset( $_GET[ self::ACTION ], $_GET['_wpnonce'] ) ) {
				return;
			}

			if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_GET['_wpnonce'] ) ), self::ACTION ) || ! current_user_can( 'manage_options' ) ) {
				return;
			}

			if ( self::BIGGOPTI_ID === sanitize_key( wp_unslash( $_GET[ self::ACTION ] ) ) ) {
				self::dismiss();
			}

			wp_safe_redirect( remove_query_arg( [ self::ACTION, '_wpnonce' ] ) );
			exit;
		}
	}

	BdThemes_Deals_Biggopti::init();
